package com.wizzadrds.theworldremembers;
import com.wizzadrds.theworldremembers.rumor.*; import com.wizzadrds.theworldremembers.memory.*; import net.fabricmc.fabric.api.gametest.v1.GameTest; import net.minecraft.gametest.framework.GameTestHelper; import net.minecraft.world.entity.EntityTypes; import java.util.UUID;
public final class RumorConversationGameTest{@GameTest public void nearbyNpcsExchangeGroundedKnowledge(GameTestHelper c){var a=c.spawn(EntityTypes.VILLAGER,2,1,2);var b=c.spawn(EntityTypes.VILLAGER,4,1,2);var player=UUID.randomUUID();var mm=MemoryManager.get(c.getLevel().getServer());mm.rememberEvent(a.getUUID(),player,MemoryEventType.NPC_DIED,0,MemoryImportance.IMPORTANT);c.runAtTickTime(200,()->{TheWorldRemembers.processWorld(c.getLevel());var facts=KnowledgeManager.get(c.getLevel().getServer()).facts(b.getUUID());if(facts.stream().noneMatch(f->f.subject().equals(player)&&f.origin()==KnowledgeOrigin.REPORTED)){c.fail("NPC did not receive reported knowledge");return;}if(ConversationManager.get(c.getLevel().getServer()).all().isEmpty()){c.fail("Conversation was not persisted");return;}c.succeed();});}}
